-- public._st_asrasteragg_transfn (function)
CREATE OR REPLACE FUNCTION public._st_asrasteragg_transfn(staterast raster, geom geometry, val double precision, rast raster, pixeltype text, nodataval double precision, uniontype text, touched boolean)
 RETURNS raster
 LANGUAGE plpgsql
AS $function$
DECLARE
  tmprast RASTER;
BEGIN
  tmprast := public.ST_AsRaster(geom, rast,
    pixeltype => pixeltype,
    value => val,
    nodataval => nodataval,
    touched => touched
  );

  IF staterast IS NULL THEN
    staterast = tmprast;
  ELSE
    SELECT public.ST_Union(r, uniontype)
    FROM ( VALUES (staterast), (tmprast) ) AS foo(r)
    INTO staterast;
  END IF;

  RETURN staterast;
END;
$function$
;

